// nonprint contains the code point ranges which do not occupy any cells.
var nonprintTable = table{
	{0x0000, 0x001F}, {0x007F, 0x009F}, {0x00AD, 0x00AD},
	{0x070F, 0x070F}, {0x180B, 0x180E}, {0x200B, 0x200F},
	{0x2028, 0x202E}, {0x206A, 0x206F}, {0xD800, 0xDFFF},
	{0xFEFF, 0xFEFF}, {0xFFF9, 0xFFFB}, {0xFFFE, 0xFFFF},
}

// runeWidth returns the number of cells a single rune occupies.
func runeWidth(r rune) int {
	switch {
	case r < 0 || r > 0x10FFFF || inTable(r, nonprintTable) || inTable(r, combiningTable):
		return 0
	case inTable(r, doublewidthTable):
		return 2
	default:
		return 1
	}
}

// inTable reports whether r is contained in one of the table ranges.
func inTable(r rune, t table) bool {
	if len(t) == 0 || r < t[0][0] || r > t[len(t)-1][1] {
		return false
	}
	lo, hi := 0, len(t)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		switch {
		case r < t[mid][0]:
			hi = mid - 1
		case r > t[mid][1]:
			lo = mid + 1
		default:
			return true
		}
	}
	return false
}
