package table

import (
	"io"
	"regexp"
	"strings"
)

// maxTextWidth is the maximum display width used when wrapping cell content.
const maxTextWidth = 30

// ANSI escape sequences do not occupy any cells on screen, therefore they are
// removed before the display width of a string is calculated.
var ansiSequence = regexp.MustCompile("\033\\[[0-9;]*[mK]")

// Table writes headers and rows in an ASCII or Markdown table layout.
type Table struct {
	out    io.Writer
	border bool
}

// New returns a table writer which writes to w. When markdown is true the table
// is rendered as a Markdown table, otherwise the plain ASCII style is used.
func New(w io.Writer, markdown bool) *Table {
	return &Table{out: w, border: !markdown}
}

// Render writes the given headers and rows to the underlying writer.
func (t *Table) Render(headers []string, rows [][]string) {
	widths := make([]int, len(headers))
	head := make([][]string, len(headers))
	for i, h := range headers {
		head[i] = wrap(h, maxTextWidth)
		widths[i] = widest(head[i])
	}
	body := make([][][]string, len(rows))
	for r, row := range rows {
		cells := make([][]string, len(row))
		for i, cell := range row {
			cells[i] = wrap(cell, maxTextWidth)
			if w := widest(cells[i]); w > widths[i] {
				widths[i] = w
			}
		}
		body[r] = cells
	}
	if t.border {
		t.line(widths)
	}
	t.row(head, widths)
	t.line(widths)
	for _, cells := range body {
		t.row(cells, widths)
	}
	if t.border {
		t.line(widths)
	}
}

// line writes a horizontal rule.
func (t *Table) line(widths []int) {
	corner := "+"
	if !t.border {
		corner = "|"
	}
	io.WriteString(t.out, corner)
	for _, w := range widths {
		io.WriteString(t.out, strings.Repeat("-", w))
		io.WriteString(t.out, corner)
	}
	io.WriteString(t.out, "\n")
}

// row writes a single logical row which may span several physical lines.
func (t *Table) row(cells [][]string, widths []int) {
	height := 0
	for _, c := range cells {
		if len(c) > height {
			height = len(c)
		}
	}
	for x := 0; x < height; x++ {
		io.WriteString(t.out, "|")
		for i, c := range cells {
			v := ""
			if x < len(c) {
				v = c[x]
			}
			if i == 0 {
				io.WriteString(t.out, " "+center(v, widths[i])+" |")
			} else {
				io.WriteString(t.out, " "+pad(v, widths[i])+" |")
			}
		}
		io.WriteString(t.out, "\n")
	}
}
