// widest returns the display width of the widest line of the given strings.
func widest(lines []string) int {
	width := 0
	for _, l := range lines {
		if w := displayWidth(l); w > width {
			width = w
		}
	}
	return width
}

// pad left aligns s inside a field of the given display width.
func pad(s string, width int) string {
	if gap := width - displayWidth(s); gap > 0 {
		return s + strings.Repeat(" ", gap)
	}
	return s
}

// center centers s inside a field of the given display width.
func center(s string, width int) string {
	if gap := width - displayWidth(s); gap > 0 {
		left := gap / 2
		return strings.Repeat(" ", left) + s + strings.Repeat(" ", gap-left)
	}
	return s
}

// wrap splits s into lines of at most limit display cells. Words which do not
// fit on a single line are kept as they are, lines which are flushed early are
// padded up to the limit so that the column keeps its width.
func wrap(s string, limit int) []string {
	var lines []string
	for _, part := range strings.Split(s, "\n") {
		lines = append(lines, wrapLine(part, limit)...)
	}
	if len(lines) == 0 {
		return []string{""}
	}
	return lines
}

// wrapLine wraps a single line of text.
func wrapLine(s string, limit int) []string {
	var lines []string
	var line string
	for _, word := range strings.Split(s, " ") {
		if line != "" {
			if displayWidth(line)+1+displayWidth(word) > limit {
				lines = append(lines, fill(line, limit))
				line = ""
			} else {
				line += " "
			}
		}
		line += word
	}
	if line != "" {
		lines = append(lines, line)
	}
	if len(lines) == 0 {
		lines = []string{""}
	}
	return lines
}

// fill pads s up to the given display width.
func fill(s string, limit int) string {
	if gap := limit - displayWidth(s); gap > 0 {
		return s + strings.Repeat(" ", gap)
	}
	return s
}

// displayWidth returns the number of cells a string occupies on screen.
func displayWidth(s string) int {
	width := 0
	for _, r := range ansiSequence.ReplaceAllString(s, "") {
		width += runeWidth(r)
	}
	return width
}
