package mod

import (
	"encoding/json"
	"io"
	"time"
)

// Module mirrors a single JSON object emitted by "go list -u -m -json all".
type Module struct {
	Path      string
	Version   string
	Indirect  bool
	Main      bool
	Update    *Module
	Time      *time.Time
	GoMod     string
	Dir       string
	GoVersion string
	Error     *ModuleError
	Replace   *Module
}

// ModuleError holds the error reported by "go list" for a module.
type ModuleError struct {
	Err string
}

// InvalidTimestamp reports whether the timestamp of the available update is
// older than the timestamp of the module currently in use. Modules without an
// update or without a timestamp are considered valid.
func (m *Module) InvalidTimestamp() (bool, error) {
	if m.Time == nil {
		return false, nil
	}
	if m.Update == nil {
		return false, nil
	}
	return m.Update.Time.Before(*m.Time), nil
}

// ParseModules reads the stream of JSON objects written by "go list" and
// returns every module which is not the main module of the project.
func ParseModules(reader io.Reader) ([]Module, error) {
	var modules []Module
	decoder := json.NewDecoder(reader)
	for {
		var module Module
		if err := decoder.Decode(&module); err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
		if module.Main {
			continue
		}
		modules = append(modules, module)
	}
	return modules, nil
}
