package runner

import (
	"fmt"
	"io"
	"os"

	"github.com/psampaz/go-mod-outdated/internal/mod"
	"github.com/psampaz/go-mod-outdated/internal/table"
)

// Run reads the module list from reader, renders a table on writer and exits
// with a non-zero exit code when the ci flag is set and at least one of the
// listed modules is outdated.
func Run(reader io.Reader, writer io.Writer, update, direct, ci bool, style string) error {
	modules, err := mod.ParseModules(reader)
	if err != nil {
		return err
	}
	filtered := filter(modules, update, direct)
	// The table is rendered before the exit code is evaluated so that the
	// output is always written, even when the process is about to fail.
	if err := renderTable(writer, filtered, style); err != nil {
		return err
	}
	if ci {
		exitWhenOutdated(filtered)
	}
	return nil
}

// exitWhenOutdated terminates the process with a non-zero exit code as soon as
// one of the given modules has an update available.
func exitWhenOutdated(modules []mod.Module) {
	for _, module := range modules {
		if module.Update != nil {
			os.Exit(1)
		}
	}
}

// filter keeps the modules matching the requested criteria.
func filter(modules []mod.Module, update, direct bool) []mod.Module {
	var filtered []mod.Module
	for _, module := range modules {
		if update && module.Update == nil {
			continue
		}
		if direct && module.Indirect {
			continue
		}
		filtered = append(filtered, module)
	}
	return filtered
}

// headers are the column titles of the rendered table.
var headers = []string{"Module", "Version", "New Version", "Direct", "Valid Timestamps"}

// renderTable writes the given modules as a table on writer.
func renderTable(writer io.Writer, modules []mod.Module, style string) error {
	if len(modules) == 0 {
		return nil
	}
	rows := make([][]string, 0, len(modules))
	for _, module := range modules {
		invalid, err := module.InvalidTimestamp()
		if err != nil {
			return err
		}
		var newVersion string
		if module.Update != nil {
			newVersion = module.Update.Version
		}
		rows = append(rows, []string{
			module.Path,
			module.Version,
			newVersion,
			fmt.Sprintf("%t", !module.Indirect),
			fmt.Sprintf("%t", !invalid),
		})
	}
	table.New(writer, style == "markdown").Render(headers, rows)
	return nil
}
